import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"证书链验证细节","description":"","frontmatter":{"title":"证书链验证细节","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tls-cert-chain-validation.md","filePath":"cs/tls-cert-chain-validation.md","lastUpdated":1789023840000}'),p={name:"cs/tls-cert-chain-validation.md"};function E(_,a,A,m,u,f){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="证书链验证细节" tabindex="-1">证书链验证细节 <a class="header-anchor" href="#证书链验证细节" aria-label="Permalink to &quot;证书链验证细节&quot;">​</a></h1><div class="epigraph"><p>「有一张证书」不是验证。验证是：从信任锚走到叶，检查签名、名字、时间、用途与吊销，任何一环跳过都等于把 PKI 收成装饰。</p><footer>—— RFC 5280；RFC 6125；对照 Anderson 对 PKI 失败</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/crypto-misuse">密码学误用</a>把算法合同外的失败收成清单。下一单元从<strong>身份绑定</strong>起：主干<a href="/cs/cert-pki">证书与 PKI</a>已有链的形状。缺口是实现里常被关掉的那些检查——名字约束、EKU、路径长度、时钟。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>误用课的「关校验」在 TLS 里表现为：不验主机名、接受过期、不跟到锚、把中间当锚。RFC 5280 的路径构建与 RFC 6125 的标识。缺口是验证算法的合同，不是再讲 X.509 字段百科。</p><h3 id="自签与私有锚" tabindex="-1">自签与私有锚 <a class="header-anchor" href="#自签与私有锚" aria-label="Permalink to &quot;自签与私有锚&quot;">​</a></h3><p>私有 CA 要把锚配进信任库，而不是在客户端 <code>verify=False</code>。测试开关进生产是规格事故。</p><p><span class="marginnote">RFC 5280 路径验证；CAB 基线约束浏览器锚。本课不写如何伪造证书的步骤。时钟来自<a href="/cs/clock-drift">物理时钟</a>的假设：过期检查依赖大致正确的时间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按构建→验证签名→名匹配→KU/EKU→有效期→策略约束走一遍。指出中间证书必须由锚或下一中间签发，叶不能当锚。吊销下一课 CT 与 OCSP 的缺口先点名。</p>',12)),(e(),n(h,null,{default:r(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANCHOR%5B%22%E4%BF%A1%E4%BB%BB%E9%94%9A%22%5D%20--%3E%20SIG%5B%22%E9%AA%8C%E7%AD%BE%E5%90%8D%E4%B8%8E%E8%B7%AF%E5%BE%84%22%5D%0A%20%20SIG%20--%3E%20NAME%5B%22%E5%90%8D%E5%AD%97%E4%B8%8E%20EKU%22%5D%0A%20%20NAME%20--%3E%20TIME%5B%22%E6%9C%89%E6%95%88%E6%9C%9F%22%5D%0A%20%20TIME%20--%3E%20LEAF%5B%22%E5%8F%B6%E5%85%AC%E9%92%A5%E8%BF%9B%E6%8F%A1%E6%89%8B%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>TLS 握手里的证书只是声明。验证失败应中止，不应「警告后继续」当默认。钉死：后课 CT、ACME、攻击史都假设本课的检查还在。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部扩展 OID 列成表。证书透明下一课：验证只保证「某锚签过」，不保证「锚没被骗着签」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>误用清单之后，PKI 的合同是路径验证而不是「有文件」。</li><li>锚、签名、名字、用途、时间缺一则握手不应成功。</li><li>verify=False 与测试锚进生产同属关掉游戏。</li><li>下一课证书透明：发现误签。</li><li>出处：RFC 5280；RFC 6125；Anderson, <em>Security Engineering</em>。</li></ul>',8))])}const T=o(p,[["render",E]]);export{B as __pageData,T as default};
